import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第30章 二十圈","description":"","frontmatter":{},"headers":[],"relativePath":"第30章_二十圈.md","filePath":"第30章_二十圈.md"}'),o={name:"第30章_二十圈.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第30章-二十圈" tabindex="-1">第30章 二十圈 <a class="header-anchor" href="#第30章-二十圈" aria-label="Permalink to &quot;第30章 二十圈&quot;">​</a></h1><p>她回来之后，我们约了一次见面。</p><p>是她提的。那天晚上她说，我们谈一下吧。</p><p>我问，在哪。</p><p>她说，操场。</p><p>我说，操场有人。</p><p>她说，晚上九点，晚自习下课，那时候操场没人。</p><p>九点的操场确实没人。晚自习下课之后大部分人回宿舍，只有少数几个体育生在跑步，跑到九点半也走了。</p><p>那天我九点差五分到的。天已经全黑了，操场边上的灯只开了两盏，光是黄的。跑道上没有人，篮球场那边有几个身影，很快也没了。</p><p>她九点零几分来的。</p><p>她穿着外套，手插在口袋里。走到我面前停下，隔了大概两步。</p><p>她说，走走吧。</p><p>我们就沿着跑道走。</p><p>第一圈谁都没说话。</p><p>跑道是塑胶的，踩上去有点弹，走快了会有一阵子沙沙的声。操场外面是宿舍楼，灯亮着，一扇一扇的窗户挂在那里。</p><p>我走得比平时慢一点，她也走得慢。我们两个都没把手从口袋里拿出来。</p><p>第二圈她说，那天的事我道个歉。</p><p>我说，你道什么歉。</p><p>她说，我说得太重了。</p><p>我说，你说得不重。</p><p>她说，那你为什么不说话。</p><p>我说，我不知道说什么。</p><p>她说，你都不知道说什么，那你现在知道了吗。</p><p>我说，还是不知道。</p><p>她笑了一下。她说，你还挺诚实。</p><p>第三圈的时候她说了一件我一直不知道的事。</p><p>她说，她那天问那句话，是因为她怕。</p><p>我说，怕什么。</p><p>她说，怕我哪天会后悔。</p><p>她说，我在这边，一个人，成绩掉的，家里不知道，学校不知道。她怕我哪天忽然想通了，觉得不值。</p><p>她说，那样的话，她受不了。</p><p>我说，我不会。</p><p>她说，你现在不会。</p><p>她说，以后呢。</p><p>我那时候停下来，站在跑道上。</p><p>我说，你是不是觉得我这个人不靠谱。</p><p>她说，不是。</p><p>她说，是我不敢信。</p><p>她说，我从小到大信过的东西都不太管用。</p><p>我们接着走。</p><p>第四圈到第十圈，她讲了她家里的事。</p><p>中间有一次她停下来弯腰系鞋带，我也停下来等。她系完站起来，说，你干嘛等我。</p><p>我说，不干嘛。</p><p>她说，你走你的。</p><p>我说，一起走。</p><p>她没再说什么。</p><p>讲得比以前细。她说她妈有多长时间没跟她说过一句好话。她说她妹妹考试考了第几名，她妈会拿出去跟人说。她说她考了第几，她妈说，还行吧。</p><p>她说她做过一件事：她把自己所有的奖状都扔了。扔在楼下的垃圾桶里。第二天她妈发现，骂了她一顿。</p><p>她说，我不知道我为什么要扔。</p><p>她说，可能是想看看扔了会不会有人心疼。</p><p>我听着，没插话。</p><p>她又说了一句。</p><p>她说，第二天我妈骂我，我一句都没回。</p><p>她说，我当时心里想的是，你看，还是有人看到的。</p><p>她说，虽然是骂，但至少她看到了。</p><p>我听完这句话，喉咙里有点堵。操场上有风，是从海那边吹过来的，冷的，带着一股味。</p><p>走到第十三圈的时候，我把我憋了很久的事说了。</p><p>我说，那天我去车站了。</p><p>她说，什么车站。</p><p>我说，去你那边的车站。</p><p>我说，我坐在候车厅里，坐了四十分钟。</p><p>她说，那你为什么不坐车。</p><p>我说，因为我到了那边不知道去哪。</p><p>她停下了。她看着我，看了几秒。</p><p>她说，你傻不傻。</p><p>我说，是挺傻的。</p><p>她说，你当时要是来了也没用。</p><p>她说，我那时候手机被收了，你来了也找不到我。</p><p>我说，我知道。</p><p>她说，那你还坐那四十分钟。</p><p>我说，坐着舒服点。</p><p>她没说话。她往前走，走了一段，抬手在眼睛上擦了一下。动作很快，我看不清楚是擦汗还是擦别的。</p><p>那时候十二月，跑道上不热。</p><p>我们走了二十圈。</p><p>第二十圈走完的时候，她站在跑道的起点上。她说，行了。</p><p>我说，什么行了。</p><p>她说，账清了。</p><p>她说，以后你别再那样了。</p><p>我说，哪样。</p><p>她说，别做那种一个人办的事。</p><p>她说，你要做，就告诉我一声。</p><p>我说，好。</p><p>她说，你又说好。</p><p>我说，那我该说什么。</p><p>她想了一下，说，你说&quot;知道了&quot;。</p><p>我说，知道了。</p><p>她笑了一下。那天晚上她笑了两次，这是第二次。</p><p>我们往回走，走到操场门口就分开了。她往西楼，我往东楼。她走了几步，回头看了我一眼。</p><p>她说，早点睡。</p><p>我说，你也是。</p><p>她走了。我一直看到她进了西楼的门，门关上了，才转身去东楼。</p><p>那天晚上我没有立刻回宿舍。我在操场门口站着，等她的背影走了。</p><p>然后我去了教学楼。</p><p>那时候教学楼已经锁了，可我上不去。我在楼下站着，看三楼那个天井的方向。那里黑着，看不清栏杆。</p><p>我站了一会儿，回宿舍了。</p><p>第二天她发消息说：昨天晚上很好。</p><p>我说：什么叫很好。</p><p>她说：就是很好。</p><p>她说：你这个人总算说了点人话。</p><p>我说：我平时不说人话吗。</p><p>她说：不说。</p><p>她说：你平时只会说好。</p><p>那天晚上我把那句话抄在了本子上。抄的时候我发现，那本本子已经写了大半本。</p><p>我翻到前面看。最早那一页写的是她的名字，旁边画了一个问号。</p><p>我那时候还不知道她的名字怎么写，是凭读音记的。</p><p>现在我知道了。</p><p>我在那一页的问号上又画了一道，把它改成了一个句号。</p><p>那天晚上我躺在床上，把那二十圈在心里重新走了一遍。</p><p>我想起她在第十三圈停下来看我那几秒。那几秒她没说一句话，可我在那几秒里知道了一件事：我那天在车站坐的那四十分钟，她懂了。</p><p>我也想起她说“账清了”。</p><p>那时候我以为这是好事。两个人都把话说开了，那就是好事。</p><p>我那时候不知道，她说“账清了”的时候，是在把那几天从我们两个的账本上划掉。</p><p>划掉的东西不进她的心里。</p><p>它们进了别的地方。</p>',114)])])}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
